function remindStatus(x,n){if(x.date===today())return'Hoje · '+(x.time||'');let d=date(x.date),start=new Date(n.getFullYear(),n.getMonth(),n.getDate()),days=Math.floor((new Date(d.getFullYear(),d.getMonth(),d.getDate())-start)/86400000),leadDays=Math.ceil(Math.max(0,+x.reminderLead||0)/1440);if(days<=leadDays)return'Lembrete antecipado';return'Em '+dateText(x.date)}

