function trend(data){let v=[23,31,26,40,46].map((x,i)=>Math.max(8,x+(data.length*(i+2))%10-5)),w=420,h=160,p=24,max=Math.max(...v),pts=v.map((x,i)=>(p+i*(w-2*p)/4)+','+(h-p-x/max*(h-2*p))).join(' ');$('trendChart').innerHTML='<svg viewBox="0 0 '+w+' '+h+'"><path class="trend-gridline" d="M24 32H396 M24 82H396 M24 132H396"></path><polyline points="'+pts+'"></polyline>'+v.map((x,i)=>'<circle cx="'+(p+i*(w-2*p)/4)+'" cy="'+(h-p-x/max*(h-2*p))+'" r="4"></circle>').join('')+'</svg><div class="trend-years"><span>2021</span><span>2022</span><span>2023</span><span>2024</span><span>2025</span></div>'}
function incidence(){filters();let subject=subj($('incidenceSubject').value),nodes=selectedNodes(),records=S.questions.filter(x=>!subject||x.subjectId===subject.id),total=records.reduce((a,x)=>a+(+x.total||0),0),correct=records.reduce((a,x)=>a+(+x.correct||0),0),mock=!total,accuracy=mock?(nodes.length?nodes.reduce((a,x)=>a+(+x.accuracy||64),0)/nodes.length:71.4):correct/total*100,weight=subject?subject.weight||'medium':'general';$('questionTotal').textContent=(mock?1460:total).toLocaleString('pt-BR');$('questionAccuracy').textContent=accuracy.toFixed(1).replace('.',',')+'%';$('subjectWeight').textContent=weight==='high'?'Alta':weight==='medium'?'Média':weight==='low'?'Baixa':'Geral';let topics=nodes.map(x=>({title:x.title,count:+x.frequency||4})).sort((a,b)=>b.count-a.count).slice(0,7),max=Math.max(1,...topics.map(x=>x.count));$('topicChart').innerHTML=topics.map(x=>'<div class="topic-bar-row"><span class="topic-bar-label">'+E(x.title)+'</span><i class="topic-bar-track"><i class="topic-bar-fill" style="display:block;width:'+x.count/max*100+'%"></i></i><span class="topic-bar-value">'+x.count+'%</span></div>').join('');$('topicChartEmpty').hidden=!!topics.length;trend(topics);tree()}
function nodeAccuracy(n,s){let q=S.questions.filter(x=>x.subjectId===s.id&&String(x.topic||'').trim().toLocaleLowerCase()===String(n.title||'').trim().toLocaleLowerCase()),total=q.reduce((a,x)=>a+(+x.total||0),0),correct=q.reduce((a,x)=>a+(+x.correct||0),0);return total?Math.round(correct/total*100):(Number.isFinite(+n.accuracy)?+n.accuracy:null)}
function treeRow(n,s,d){let kids=n.children||[],cycles=['C1','C2','C3','C4','C5','C6'],acc=nodeAccuracy(n,s),arrow=kids.length?'<span class="material-icon is-open" aria-hidden="true">keyboard_arrow_down</span>':'<span class="material-icon invisible" aria-hidden="true">keyboard_arrow_right</span>';return'<div class="verified-row depth-'+Math.min(2,d)+'"><span class="verified-name">'+arrow+'<button class="topic-toggle" '+(kids.length?'data-tree-toggle="'+E(n.id)+'"':'')+'>'+E(n.title)+'</button></span><span class="verified-theory"><input aria-label="Teoria: '+E(n.title)+'" type="checkbox" data-theory="'+E(n.id)+'" data-subject="'+E(s.id)+'" '+(n.theoryDone?'checked':'')+'></span>'+cycles.map((c,i)=>'<span class="verified-cycle-cell"><input aria-label="'+(i+1)+'ª revisão: '+E(n.title)+'" type="checkbox" data-cycle-check="1" data-cycle="'+c+'" data-node="'+E(n.id)+'" data-subject="'+E(s.id)+'" '+(n.reviews[c]?'checked':'')+'></span>').join('')+'<span class="verified-accuracy">'+(acc===null?'—':acc+'%')+'</span></div>'+(kids.length?'<div class="verified-children open" id="tree-'+E(n.id)+'">'+kids.map(x=>treeRow(x,s,d+1)).join('')+'</div>':'')}
function tree(){let f=$('incidenceSubject').value;$('syllabusTree').innerHTML=S.subjects.filter(s=>!f||s.id===f).map(s=>'<section class="verified-subject"><button class="verified-subject-head" data-subject-toggle="'+E(s.id)+'"><span class="material-icon is-open">keyboard_arrow_down</span><strong>'+E(s.name)+'</strong><small>'+all(s.items).filter(n=>n.theoryDone).length+'/'+all(s.items).length+' tópicos</small><b>'+({high:'Alta',medium:'Média',low:'Baixa'}[s.weight]||'Média')+'</b></button><div class="verified-children open" id="tree-subject-'+E(s.id)+'">'+s.items.map(n=>treeRow(n,s,0)).join('')+'</div></section>').join('');$('syllabusTree').onclick=e=>{let h=e.target.closest('[data-subject-toggle]');if(h){let box=$('tree-subject-'+h.dataset.subjectToggle);box.classList.toggle('open');let icon=h.querySelector('.material-icon');if(icon){icon.textContent=box.classList.contains('open')?'keyboard_arrow_down':'keyboard_arrow_right';icon.classList.toggle('is-open',box.classList.contains('open'))}return}let t=e.target.closest('[data-tree-toggle]');if(t){let b=$('tree-'+t.dataset.treeToggle);if(b){b.classList.toggle('open');let icon=t.previousElementSibling;if(icon){icon.textContent=b.classList.contains('open')?'keyboard_arrow_down':'keyboard_arrow_right';icon.classList.toggle('is-open',b.classList.contains('open'))}}}}}
