function timerUI(){let t=S.timer,r=t.running&&t.endsAt?Math.max(0,Math.ceil((t.endsAt-Date.now())/1000)):t.remaining,paused=!t.running&&(t.wasPaused||t.remaining!==t.focus*60||t.completed>0||t.phase==='pause'||t.remaining===0);$('timerDisplay').textContent=String(Math.floor(r/60)).padStart(2,'0')+':'+String(r%60).padStart(2,'0');$('focusTimerPhase').textContent=t.phase==='focus'?'FOCO':'PAUSA';$('timerToggle').textContent=t.running?'Pausar':paused&&t.remaining>0?'Continuar':'Iniciar';$('focusMinutes').value=t.focus;$('pauseMinutes').value=t.pause;$('focusCycles').value=t.cycles;let section=document.querySelector('.focus-timer');section.classList.toggle('has-paused-actions',paused);let notice='';if(!t.running&&t.completed>=t.cycles&&t.remaining===0)notice='Ciclos concluídos. +10 min para continuar ou Finalizar.';else if(!t.running&&t.wasPaused)notice='Cronômetro pausado.';else if(t.running&&t.phase==='pause')notice=r<=10&&r>0?(t.completed+1>=t.cycles?'Finalizando ciclo em '+r+'s.':'Reiniciando ciclo em '+r+'s.'):'Hora da pausa.';else if(t.running&&t.phase==='focus'&&t.noticeUntil>Date.now())notice=t.notice||'Novo ciclo iniciado.';$('timerNotice').textContent=notice;section.classList.toggle('has-timer-notice',!!notice)}
function timerConfig(){let t=S.timer;t.focus=Math.max(1,+$('focusMinutes').value||25);t.pause=Math.max(1,+$('pauseMinutes').value||5);t.cycles=Math.max(1,+$('focusCycles').value||4);if(!t.running){t.phase='focus';t.completed=0;t.remaining=t.focus*60}save();timerUI()}
['focusMinutes','pauseMinutes','focusCycles'].forEach(x=>$(x).onchange=timerConfig);
$('timerToggle').onclick=()=>{let t=S.timer;if(t.running){tickTimer();if(t.running){t.remaining=Math.max(0,Math.ceil((t.endsAt-Date.now())/1000));t.running=false;t.endsAt=null;t.wasPaused=true;stopTimerLoop()}}else{if(t.remaining<=0||t.completed>=t.cycles){t.completed=0;t.phase='focus';t.remaining=t.focus*60}t.wasPaused=false;t.running=true;t.endsAt=Date.now()+t.remaining*1000;startTimerLoop()}save();timerUI()};
$('timerExtend').onclick=()=>{let t=S.timer;if(t.running)return;t.completed=0;t.remaining=Math.max(0,t.remaining)+600;t.phase='focus';t.wasPaused=true;save();timerUI()};
$('timerFinish').onclick=()=>{let t=S.timer;stopTimerLoop();t.running=false;t.endsAt=null;t.phase='focus';t.completed=0;t.remaining=0;t.wasPaused=true;save();timerUI()};
function startTimerLoop(){if(timerInterval===null)timerInterval=setInterval(tickTimer,1000)}
function stopTimerLoop(){if(timerInterval!==null){clearInterval(timerInterval);timerInterval=null}}
function tickTimer(){let t=S.timer;if(!t.running||!t.endsAt){stopTimerLoop();return}let now=Date.now(),changed=false;while(t.running&&t.endsAt<=now){if(t.phase==='focus'){t.phase='pause';t.remaining=t.pause*60;t.notice='Hora da pausa.';t.noticeUntil=0}else{t.completed++;if(t.completed>=t.cycles){t.running=false;t.phase='focus';t.remaining=0;t.endsAt=null;t.wasPaused=false;t.notice='Ciclos concluídos.';t.noticeUntil=0;break}t.phase='focus';t.remaining=t.focus*60;t.notice='Novo ciclo iniciado.';t.noticeUntil=now+4000}if(t.running)t.endsAt+=t.remaining*1000;changed=true}if(t.running)t.remaining=Math.max(0,Math.ceil((t.endsAt-now)/1000));if(changed)save();timerUI();if(!t.running)stopTimerLoop()}
